    # c1, c2 範圍是 0-k (最大 200), m1 範圍是 0-127
    # 使用字典來減少稀疏狀態的記憶空間
    dp = {} # (c1, m1, c2) -> bitset (int)
    dp[(0, 0, 0)] = 1

    for x in nums:
        new_dp = dp.copy()
        for (c1, m1, c2), mask2_bits in dp.items():
