                key = (c1 + 1, m1 | x, c2)
                new_dp[key] = new_dp.get(key, 0) | mask2_bits
            # 選入第二組
            if c2 < k:
                # 更新 bitset：所有原本的 m2 都變成 m2 | x
                res_bits = 0
                for m2 in range(128):
                    if (mask2_bits >> m2) & 1:
                        res_bits |= (1 << (m2 | x))
                key = (c1, m1, c2 + 1)
                new_dp[key] = new_dp.get(key, 0) | res_bits
        dp = new_dp

    ans = 0
    for (c1, m1, c2), mask2_bits in dp.items():
        if c1 == k and c2 == k:
            # 遍歷所有可能的 m2 位元
            for m2 in range(128):
                if (mask2_bits >> m2) & 1:
                    if (m1 ^ m2) > ans:
