            u = q.popleft()
            ux, uy = pts[u]
            for dx, dy in moves:
                vx, vy = ux + dx, uy + dy
                if 0 <= vx < 50 and 0 <= vy < 50:
                    # Check if this coordinate is one of our points
                    for v in range(n):
                        if pts[v] == [vx, vy]:
                            if dist[i][v] == float('inf'):
                                dist[i][v] = dist[u][i] + 1 # Logic error fix: dist[i][v] = dist[i][u] + 1
                                # Correction: The BFS should be standard. Let's rewrite slightly cleaner.
                                pass

    # Re-writing BFS correctly for all points
    for i in range(n):
        dist[i][i] = 0
        q = deque([i])
        d_row = [float('inf')] * n
        d_row[i] = 0
        while q:
            u = q.popleft()
            ux, uy = pts[u]
            for dx, dy in moves:
                vx, vy = ux + dx, uy + dy
                if 0 <= vx < 50 and 0 <= vy < 50:
                    # We need to find which point index v matches [vx, vy]
                    # But we can just BFS the whole board or use a map
                    pass

    # Optimized BFS: Map coordinates to indices
    coord_to_idx = {p: i for i, p in enumerate(pts)}
    for i in range(n):
        q = deque([i])
        dist[i][i] = 0
        while q:
            u = q.popleft()
            ux, uy = pts[u]
            for dx, dy in moves:
                vx, vy = ux + dx, uy + dy
                if (vx, vy) in coord_to_idx:
                    v = coord_to_idx[(vx, vy)]
                    if dist[i][v] == float('inf'):
                        dist[i][v] = dist[i][u] + 1
                        q.append(v)

    # DP with memoization (Minimax)
    # state: (current_pos_idx, mask_of_remaining_pawns)
    memo = {}

    def solve(curr_idx, mask):
        if mask == 0:
            return 0
        state = (curr_idx, mask)
        if state in memo:
            return memo[state]

        # Alice wants to maximize, Bob wants to minimize. 
        # We can determine turn by counting set bits in mask.
        # Total pawns initially is len(positions).
        pawns_left = bin(mask).count('1')
        is_alice = (len(positions) - pawns_left) % 2 == 0

        res = -float('inf') if is_alice else float('inf')

        for i in range(len(positions)):
            if (mask >> i) & 1:
                p_idx = i + 1 # pts[0] is kx, ky
                d = dist[curr_idx][p_idx]
                val = d + solve(p_idx, mask ^ (1 << i))
                if is_alice:
                    res = max(res, val)
                else:
                    res = min(res, val)

        memo[state] = res
        return res

    # Initial mask: all pawns present
    initial_mask = (1 << len(positions)) - 1
    return solve(0, initial_mask)
