from typing import List
from collections import deque

def maxMoves(kx: int, ky: int, positions: List[List[int]]) -> int:
    # Precompute distances between all points of interest (knight start + pawns)
    nodes = [(kx, ky)] + positions
    n = len(nodes)
    dist = [[float('inf')] * n for _ in range(n)]

    moves = [(2, 1), (2, -1), (-2, 1), (-2, -1), (1, 2), (1, -2), (-1, 2), (-1, -2)]

    for i in range(n):
        dist[i][i] = 0
        q = deque([i])
        d_map = {i: 0}
        while q:
            u = q.popleft()
            ux, uy = nodes[u]
            for dx, dy in moves:
                vx, vy = ux + dx, uy + dy
                if 0 <= vx < 50 and 0 <= vy < 50:
                    # Find if this coordinate is one of our target nodes
                    for v in range(n):
                        if nodes[v] == (vx, vy) and v not in d_map:
                            d_map[v] = d_map[u] + 1
                            q.append(v)
        for j in range(n):
            dist[i][j] = d_map.get(j, float('inf'))

    # Memoization for DP
    # state: (current_node_index, bitmask_of_remaining_pawns)
    memo = {}

    def solve(curr_idx: int, mask: int, is_alice: bool) -> int:
        if mask == 0:
            return 0
        state = (curr_idx, mask, is_alice)
        if state in memo:
            return memo[state]

        res = -float('inf') if is_alice else float('inf')

        for i in range(1, n):
            if (mask >> (i - 1)) & 1:
                d = dist[curr_idx][i]
                # The problem states they choose the pawn that takes fewest moves to capture
                # but "the player can select any pawn". Actually, the wording implies
                # we must find the shortest path for a chosen pawn.
                score = solve(i, mask ^ (1 << (i - 1)), not is_alice)
                current_val = d + score

                if is_alice:
                    res = max(res, current_val)
                else:
                    res = min(res, current_val)

        memo[state] = res
        return res

    # Initial mask: all pawns (bits 0 to n-2 represent positions[0...n-2])
    # Wait, nodes[1:] are the pawns. So there are len(positions) pawns.
    initial_mask = (1 << (len(positions))) - 1
    return solve(0, initial_mask, True)
