            x, y = points[u]
            for dx, dy in [(1,2),(1,-2),(-1,2),(-1,-2),(2,1),(2,-1),(-2,1),(-2,-1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 50 and 0 <= ny < 50:
                    # Check if (nx, ny) is one of our points
                    for v in range(n):
                        if points[v] == (nx, ny):
                            if dist[i][v] == float('inf'):
                                dist[i][v] = dist[i][u] + 1
                                q.append(v)
                                break

    # 2. Minimax with Memoization (Bitmask DP)
    memo = {}

    def solve(curr_idx, mask):
