        if j >= n:
            # Only one element left at index i
            return nums[i] if i < n else 0

        k = j + 1
        while k < n and (k == i or k == j):
            k += 1

        if k >= n:
            # Only two elements left at indices i and j
            return max(nums[i], nums[j])

        state = (i, j)
        if state in memo:
            return memo[state]

        # Option 1: Remove (i, j), leave k. Next set is {k, k+1, k+2}
        # Note: Since we remove i and j, the next available indices are k, k+1, k+2
        res = max(nums[i], nums[j]) + solve_v13(k, k + 1)

        # Option 2: Remove (i, k), leave j. Next set is {j, k+1, k+2}
        res = min(res, max(nums[i], nums[k]) + solve_v13(j, k + 1))

        # Option 3: Remove (j, k), leave i. Next set is {i, k+1, k+2}
        res = min(res, max(nums[j], nums[k]) + solve_v13(i, k + 1))

        memo[state] = res
        return res

    if n == 0:
        return 0
    if n == 1:
        return nums[0]
    if n == 2:
        return max(nums[0], nums[1])

    # The first three elements are at indices 0, 1, 2.
    # We need to find the min cost starting from these three.
    # However, we must be careful with the recursion logic. 
    # Let's use a more robust state: solve(i, j, k) where i < j < k are current indices.
    memo_v14 = {}

    def solve_v14(indices):
        if len(indices) == 0:
            return 0
        if len(indices) == 1:
            return nums[indices[0]]
        if len(indices) == 2:
            return max(nums[indices[0]], nums[indices[1]])

        if indices in memo_v14:
            return memo_v14[indices]

        i1, i2, i3 = indices[0], indices[1], indices[2]

        # Find the next two available indices after i3
        next_indices_base = []
        curr = i3 + 1
        while len(next_indices_base) < 2 and curr < n:
            if curr != i1 and curr != i2 and curr != i3:
                next_indices_base.append(curr)
            curr += 1

        # Option 1: Remove (i1, i2), leave i3
        res = max(nums[i1], nums[i2]) + solve_v14(tuple(sorted([i3] + next_indices_base)))

        # Option 2: Remove (i1, i3), leave i2
        res = min(res, max(nums[i1], nums[i3]) + solve_v14(tuple(sorted([i2] + next_indices_base))))

        # Option 3: Remove (i2, i3), leave i1
        res = min(res, max(nums[i2], nums[i3]) + solve_v14(tuple(sorted([i1] + next_indices_base))))

        memo_v14[indices] = res
        return res

    # The initial indices are 0, 1, 2. But we must handle cases where n < 3 first.
    if n < 3:
        if n == 0: return 0
        if n == 1: return nums[0]
        return max(nums[0], nums[1])

