    larger = []
    for i, (x, y) in enumerate(coordinates):
        if i == k: continue
        if x < target[0] and y < target[1]:
            smaller.append((x, y))
        elif x > target[0] and y > target[1]:
            larger.append((x, y))

    def get_max_len(pts):
        # Sort by x primarily, then y
        pts.sort()
        # LIS using patience sorting logic (O(N log N))
        tails = []
        for _, y in pts:
            import bisect
            idx = bisect.bisect_left(tails, y)
            if idx < len(tails):
                tails[idx] = y
            else:
                tails.append(y)
        return len(tails)

    # The longest path containing target is LIS of smaller points + 1 + LIS of larger points
    # But wait, the standard LIS doesn't guarantee a valid "path" chain because of y constraints.
    # Correct approach: Since we need x_i < x_{i+1} and y_i < y_{i+1}, 
    # after sorting by x, it becomes a standard LIS on the y-coordinates.

    def solve(pts):
        pts.sort()
        tails = []
        import bisect
        for _, y in pts:
            idx = bisect.bisect_left(tails, y)
            if idx < len(tails):
                tails[idx] = y
            else:
                tails.append(y)
        return len(tails)

    # Because we need the path to be strictly increasing in both x and y:
    # 1. For 'smaller' points, they must all have x < target[0] and y < target[1].
    # 2. After sorting by x, any LIS of their y-coordinates will satisfy the condition.
    return solve(smaller) + 1 + solve(larger)
